# Billy the Kid et son monde : les fils francophones (Maxwell-Beaubien, Godfroy, Fountain). Livres du dossier
# BILLY_THE_KID du Drive de l'auteur. Corpus « Recherches », préfixe BTK. Éditions numériques non paginées : les
# renvois donnent la page du PDF.
from commun import Corpus
WA = "Wallis, Michael (2007), Billy the Kid: The Endless Ride, New York, W. W. Norton"
UT = "Utley, Robert M. (2015), Wanted: The Outlaw Lives of Billy the Kid and Ned Kelly, New Haven, Yale University Press"
GA = "Garrett, Pat F. (1882), The Authentic Life of Billy, the Kid, Santa Fe, New Mexican Printing and Publishing"
GR = "Groves, Melody (2021), Before Billy the Kid: The Boy Behind the Legendary Outlaw, Guilford, TwoDot"
C = Corpus('Recherches', 'BTK', WA, page_fmt='PDF p. {}')
F = C.F
F('01', "Fort Sumner : la maison Maxwell, ancien quartier des officiers, et les hommes de Pete Maxwell (1878)", 'etablissement', '1870~/1881', -104.1930, 34.4045, 'c', ['Lucien Maxwell', 'Pete Maxwell', 'Luz Beaubien Maxwell', 'Charlie Bowdre', 'Doc Scurlock'],
  "Quand l'armée abandonne Fort Sumner en 1868, Lucien Maxwell, après la vente de sa concession, achète les bâtiments et s'y retire ; à sa mort en 1875, son fils aîné Pete reprend le ranch, dont le siège est l'ancien poste. La famille habite l'ancien quartier des officiers. En 1878, deux compagnons de Billy, Charlie Bowdre et Doc Scurlock, quittent les Regulators, s'installent à Fort Sumner avec leurs familles et travaillent pour Pete Maxwell ; Garrett précise que Bowdre y garde le bétail. Fort Sumner, peuplé surtout de bergers hispaniques, devient le refuge favori de Billy.",
  '200', "Pete (Pedro) Maxwell est le petit-fils de Charles Beaubien par sa mère Luz. Utley (2015) attribue l'achat du fort à Pete ; Wallis et l'atlas, à Lucien. En français, l'histoire a été racontée par le Québécois Éric Veillette (Billy, 2008), qui fait intervenir Luz Beaubien Maxwell, et par Éric Vuillard (Les orphelins, roman, 2019).", source=WA)
F('02', "Fort Sumner, 24 décembre 1880 : les adieux de Billy à Paulita Maxwell", 'evenement', '1880-12-24', -104.1925, 34.4040, 'c', ['Paulita Maxwell', 'Luz Beaubien Maxwell', 'Deluvina Maxwell', 'Pat Garrett', 'Jim East'],
  "Capturé à Stinking Springs, Billy est ramené enchaîné à Fort Sumner la veille de Noël 1880. Deluvina Maxwell, servante navajo capturée enfant par des Apaches et échangée à Lucien Maxwell contre dix chevaux, très attachée au Kid, obtient de Garrett qu'il puisse dire adieu à Paulita Maxwell. Escorté de Jim East et Lee Hall et toujours enchaîné à Dave Rudabaugh, il entre dans l'ancien quartier des officiers ; doña Luz Maxwell, la mère de Paulita, demande en vain qu'on lui ôte ses chaînes pour un moment d'intimité. East racontera qu'il fallut séparer les amoureux pour reprendre la route de Las Vegas.",
  '217', "Utley (2015, PDF p. 102) rapporte la même scène : c'est « Mother » Maxwell, veuve de Lucien, qui implore Garrett.", source=WA)
F('03', "Fort Sumner, 14 juillet 1881 : la mort de Billy dans la chambre de Pete Maxwell", 'evenement', '1881-07-14', -104.1928, 34.4042, 'c', ['Pete Maxwell', 'Deluvina Maxwell', 'Paulita Maxwell', 'Pat Garrett'],
  "Évadé de Lincoln, Billy revient à Fort Sumner. Dans la nuit du 14 juillet 1881, Garrett l'attend dans la chambre obscure de Pete Maxwell et l'abat d'une balle au-dessus du cœur ; Maxwell pose une chandelle sur le rebord de la fenêtre pour que les adjoints voient le corps. Au matin, la foule envahit l'ancienne place d'armes ; Deluvina Maxwell frappe Garrett de ses poings en l'injuriant, les femmes consolent Paulita, et Garrett et ses adjoints se barricadent dans la maison Maxwell. Billy est inhumé dans le vieux cimetière militaire, où reposait déjà Lucien Maxwell et où Garrett avait fait enterrer Tom O'Folliard et Charlie Bowdre.",
  '216, 226', "Point au site historique de Fort Sumner ; la tombe est voisine.", source=WA)
F('04', "Près de Puerto de Luna : le ranch de Pablo Beaubien, relais de Garrett (décembre 1880)", 'evenement', '1880-12-17/1880-12-18', -104.560, 34.770, 'h', ['Pablo Beaubien', 'Pat Garrett', 'Alexander Grzelachowski'],
  "Parti du magasin de Grzelachowski à Puerto de Luna le 17 décembre 1880 avant une tempête, Garrett fait halte avec sa troupe au ranch de Pablo Beaubien, à un mille au-dessus de celui de Gayheart. C'est là que son éclaireur, revenu de Fort Sumner en se faisant passer pour un berger cherchant des bêtes égarées, lui confirme que le Kid et cinq compagnons s'y trouvent ; la troupe repart et essuie le blizzard à vingt-cinq milles au-dessus de Fort Sumner.",
  '68', "Le lien de Pablo Beaubien avec la famille de Charles Beaubien n'est pas établi par ces sources. Position hypothétique sur le Pecos, en aval de Puerto de Luna.", source=GA)
F('05', "Blazer's Mill : l'agence de Mescalero de Frederick C. Godfroy et la fusillade du 4 avril 1878", 'evenement', '1878-04-04', -105.785, 33.162, 'a', ['Frederick C. Godfroy', 'Clara Godfroy', 'Joseph Blazer', 'Buckshot Roberts', 'Dick Brewer'],
  "Le dentiste Joseph Blazer loue sa grande maison d'adobe à étage, en amont de sa scierie, au gouvernement fédéral pour loger l'agent des Apaches mescaleros, Frederick C. Godfroy, et sa famille ; l'agence y a son siège, et Mme Clara Godfroy sert des repas aux voyageurs. Le 4 avril 1878, les Regulators, dont Billy, s'y arrêtent pour dîner quand arrive Buckshot Roberts ; Brewer tente de faire expulser Roberts par Blazer et Godfroy, puis l'assaut tourne au drame : Roberts blessé à mort tue Brewer d'une balle de Springfield.",
  '186', "Nom de famille d'origine française ; ces livres ne disent rien des origines de Godfroy (le lien éventuel avec les Godfroy de Détroit reste à vérifier). Utley (2015, PDF p. 48-51) donne le même récit. Le grand jury de Lincoln releva en 1878 de fortes présomptions de fraude contre l'agent Godfroy (Larson, Forgotten Frontier, 1993).", source=WA)
F('06', "La Mesilla, avril 1881 : Albert J. Fountain, fils d'une huguenote française, défenseur de Billy", 'personnage', '1877/1881-04-09', -106.7950, 32.2735, 'c', ['Albert Jennings Fountain', 'John Bail', 'Warren Bristol'],
  "Né en 1838 à Staten Island d'un père capitaine de navire et d'une mère huguenote française, Albert Jennings Fountain a couru le monde (prisonnier à Canton, chercheur d'or en Californie, évadé de Nicaragua déguisé en femme) avant de devenir avocat et rédacteur du Mesilla Valley Independent, où il dénonce en 1877 les « banditti » de Jesse Evans, parmi lesquels chevauche brièvement le jeune Antrim. En avril 1881, le juge Bristol le nomme avec John Bail défenseur du Kid ; le 9 avril, après deux jours d'audience, Billy est reconnu coupable du meurtre du shérif Brady.",
  '123-125', "Fountain disparaîtra lui-même en 1896. Point à la plaza de La Mesilla.", source=WA)
fiches = C.fiches
